import {validPrefabLink} from './prefab-link.js';
import {objectComponents} from './scene-components.js';
import {remapActorReferences} from './actor-references.js';
import {validScene,defaultSurface} from './model.js';
import {resolvePrefab,setPrefabOverride} from './prefab-variants.js';
const copy=v=>v===undefined?undefined:structuredClone(v);
const excluded=new Set(['id','prefabAsset','prefabRoot','prefabLocalId','prefabLink','gameplayDebug','actorClasses','tileColliders','runtimeTilemap','runtimeTilemapPath','tilemapDirty','currentSprite']);
const safe=p=>Array.isArray(p)&&p.length>0&&p.length<=32&&p.every(k=>(typeof k==='string'||Number.isInteger(k))&&!['__proto__','prototype','constructor'].includes(String(k)));
const equal=(a,b)=>a===b||Array.isArray(a)&&Array.isArray(b)&&a.length===b.length&&a.every((v,i)=>equal(v,b[i]))||a&&b&&typeof a==='object'&&typeof b==='object'&&!Array.isArray(a)&&!Array.isArray(b)&&Object.keys(a).length===Object.keys(b).length&&Object.keys(a).every(k=>Object.hasOwn(b,k)&&equal(a[k],b[k]));
function normalize(rows){return rows.map(value=>{const o=copy(value);for(const key of excluded)if(key!=='id')delete o[key];if(o.components===undefined){objectComponents(o);o.components.forEach((c,i)=>c.id=c.type+'_'+i);}return o;});}
function checkLink(root){const l=root?.prefabLink;if(!validPrefabLink(l))throw Error('프리팹 인스턴스 연결 데이터 오류');return l;}
function worldRows(local,link){const ids=new Map(Object.entries(link.ids)),rows=copy(local);for(const o of rows){const local=o.id;o.id=ids.get(local);o.prefabAsset=link.asset;o.prefabRoot=link.ids[link.root];o.prefabLocalId=local;}remapActorReferences(rows,[],ids);return rows;}
function localRows(objects,link){const rows=objects.filter(o=>o.prefabRoot===link.ids[link.root]).map(o=>{const v=copy(o);v.id=o.prefabLocalId;for(const k of excluded)if(k!=='id')delete v[k];return v;}),ids=new Map(Object.entries(link.ids).map(([a,b])=>[b,a]));remapActorReferences(rows,[],ids);return rows;}
export function createPrefabInstance(asset,data,{id=()=>crypto.randomUUID()}={}){const baseline=normalize(data.objects),ids=Object.fromEntries(baseline.map(o=>[o.id,id()])),link={version:1,asset,root:data.root,baseline,ids,conflicts:[],dependencies:data.dependencies||[asset],sourceRevision:data.sourceRevision||''},rows=worldRows(baseline,link),root=rows.find(o=>o.id===ids[data.root]);root.prefabLink=link;return rows;}
export function prefabRootFor(objects,object){return objects.find(o=>o.id===(object?.prefabRoot||object?.id)&&o.prefabLink);}
function differences(a,b,path=[],out=[]){if(equal(a,b))return out;if(path.at(-1)==='components'&&Array.isArray(a)&&Array.isArray(b)){const before=new Map(a.map(c=>[c.id,c])),after=new Map(b.map(c=>[c.id,c]));for(const id of new Set([...before.keys(),...after.keys()]))differences(before.get(id),after.get(id),[...path,id],out);}
 else if(a&&b&&typeof a==='object'&&typeof b==='object'&&!Array.isArray(a)&&!Array.isArray(b)){for(const key of new Set([...Object.keys(a),...Object.keys(b)]))if(key!=='id')differences(a[key],b[key],[...path,key],out);}
 else if(['position','rotation','scale'].includes(path.at(-1))&&Array.isArray(a)&&Array.isArray(b)){for(let i=0;i<3;i++)differences(a[i],b[i],[...path,i],out);}
 else out.push({path,before:copy(a),value:copy(b),deleted:b===undefined});return out;}
export function prefabInstanceChanges(objects,root){const link=checkLink(root),current=localRows(objects,link),currentById=new Map(current.map(o=>[o.id,o])),baseIds=new Set(link.baseline.map(o=>o.id)),rows=[];for(const base of link.baseline){const o=currentById.get(base.id);if(!o){rows.push({object:base.id,path:[],before:base,deleted:true});continue;}for(const change of differences(base,o)){if(base.id===link.root&&['parent','parentId','position','rotation'].includes(change.path[0]))continue;rows.push({object:base.id,...change});}}for(const o of current)if(!baseIds.has(o.id))rows.push({object:o.id,path:[],value:o,added:true});return rows;}
function merge(base,current,source,path,conflicts){if(equal(base,current))return copy(source);if(equal(base,source)||equal(current,source))return copy(current);
 if(path.at(-1)==='components'&&[base,current,source].every(Array.isArray)){const b=new Map(base.map(c=>[c.id,c])),c=new Map(current.map(c=>[c.id,c])),s=new Map(source.map(c=>[c.id,c]));return [...new Set([...s.keys(),...c.keys()])].map(id=>merge(b.get(id),c.get(id),s.get(id),[...path,id],conflicts)).filter(Boolean);}
 if([base,current,source].every(v=>v&&typeof v==='object'&&!Array.isArray(v))){const out={};for(const key of new Set([...Object.keys(source),...Object.keys(current)])){const v=merge(base[key],current[key],source[key],[...path,key],conflicts);if(v!==undefined)out[key]=v;}return out;}
 if(['position','rotation','scale'].includes(path.at(-1))&&[base,current,source].every(Array.isArray))return source.map((v,i)=>merge(base[i],current[i],v,[...path,i],conflicts));
 conflicts.push({object:path[0],path:path.slice(1),before:copy(base),value:copy(current),source:copy(source),deleted:current===undefined});return copy(current);
}
export function refreshPrefabInstance(objects,root,resolved,{id=()=>crypto.randomUUID()}={}){const old=checkLink(root),source=normalize(resolved.objects),current=localRows(objects,old),conflicts=[],merged=[];if(resolved.root!==old.root)throw Error('프리팹 루트 ID가 바뀌었어요. 새 인스턴스로 배치하세요.');const link=copy(old);for(const o of source)if(!Object.hasOwn(link.ids,o.id))link.ids[o.id]=id();
 const bases=new Map(old.baseline.map(o=>[o.id,o])),locals=new Map(current.map(o=>[o.id,o])),sources=new Map(source.map(o=>[o.id,o]));for(const key of new Set([...sources.keys(),...locals.keys()])){const b=bases.get(key),c=locals.get(key),s=sources.get(key),v=merge(b,c,s,[key],conflicts);if(v)merged.push(v);}
 const localRoot=merged.find(o=>o.id===link.root),placed=current.find(o=>o.id===link.root);if(!localRoot||!placed)throw Error('인스턴스 루트는 삭제할 수 없어요.');for(const key of ['position','rotation','parent','parentId']){if(Object.hasOwn(placed,key))localRoot[key]=copy(placed[key]);else delete localRoot[key];}const read=(row,path)=>{if(!path.length)return row;try{return access(row,path,false);}catch{return undefined;}};for(const oldConflict of old.conflicts){if(conflicts.some(c=>c.object===oldConflict.object&&equal(c.path,oldConflict.path)))continue;const value=read(merged.find(o=>o.id===oldConflict.object),oldConflict.path),latest=read(sources.get(oldConflict.object),oldConflict.path);if(!equal(value,latest))conflicts.push({...copy(oldConflict),value:copy(value),source:copy(latest),deleted:value===undefined});}link.baseline=source;link.dependencies=resolved.dependencies||[link.asset];link.sourceRevision=resolved.sourceRevision||link.sourceRevision;link.conflicts=conflicts.filter(c=>!(c.object===link.root&&['position','rotation','parent','parentId'].includes(c.path[0])));const rows=worldRows(merged,link);rows.find(o=>o.id===root.id).prefabLink=link;const removed=new Set(objects.filter(o=>o.prefabRoot===root.id&&!rows.some(n=>n.id===o.id)).map(o=>o.id)),next=objects.filter(o=>o.prefabRoot!==root.id).concat(rows);for(const o of next)if(removed.has(o.parent||o.parentId))throw Error('삭제될 프리팹 자식에 외부 오브젝트가 연결돼 있어요. 먼저 부모를 옮기세요.');if(!validScene({version:1,objects:next,surface:defaultSurface}))throw Error('프리팹 병합 결과의 계층·속성을 확인하세요.');return {objects:next,conflicts:link.conflicts,removed:[...removed]};}
function access(o,path,write,value,remove=false){if(!safe(path))throw Error('프리팹 속성 경로 오류');let at=o;for(let i=0;i<path.length-1;i++){const key=path[i];at=key==='components'&&Array.isArray(at.components)?at.components: Array.isArray(at)&&typeof key==='string'?at.find(c=>c.id===key):at?.[key];if(!at||typeof at!=='object')throw Error('프리팹 속성 경로가 없어요.');}const key=path.at(-1);if(Array.isArray(at)&&typeof key==='string'){const i=at.findIndex(c=>c.id===key);if(!write)return at[i];if(remove){if(i>=0)at.splice(i,1);}else if(i>=0)at[i]=copy(value);else at.push(copy(value));return;}if(!write)return at[key];if(remove)delete at[key];else at[key]=copy(value);}
export function revertPrefabProperty(objects,root,object,path){const l=checkLink(root),base=l.baseline.find(o=>o.id===object),rows=localRows(objects,l),current=rows.find(o=>o.id===object);if(!base||!current||!safe(path)||object===l.root&&['parent','parentId','position','rotation'].includes(path[0]))throw Error('복원할 프리팹 속성을 확인하세요.');const value=access(base,path,false);access(current,path,true,value,value===undefined);const result=worldRows(rows,l);result.find(o=>o.id===root.id).prefabLink={...copy(l),conflicts:l.conflicts.filter(c=>!(c.object===object&&equal(c.path.slice(0,path.length),path)))};return objects.filter(o=>o.prefabRoot!==root.id).concat(result);}
export function applyPrefabProperty(data,resolved,objects,root,object,path){const l=checkLink(root),current=localRows(objects,l).find(o=>o.id===object),source=normalize(resolved.objects).find(o=>o.id===object);if(!current||!source||!safe(path)||object===l.root&&['parent','parentId','position','rotation'].includes(path[0]))throw Error('적용할 프리팹 속성을 확인하세요.');const value=access(current,path,false),next=copy(data),draft=copy(source);access(draft,path,true,value,value===undefined);next.overrides=(next.overrides||[]).filter(o=>!(o.object===object&&o.path[0]===path[0]));const own=next.objects.find(o=>o.id===object);if(own){if(draft[path[0]]===undefined)delete own[path[0]];else own[path[0]]=copy(draft[path[0]]);}else{if(draft[path[0]]===undefined)throw Error('상속 속성 삭제 대신 원본 컴포넌트 편집을 사용하세요.');setPrefabOverride(next,object,[path[0]],draft[path[0]]);}return next;}
export function remapPrefabInstanceReferences(objects,bindings){for(const root of objects.filter(o=>o.prefabLink)){const link=checkLink(root),rows=objects.filter(o=>o.prefabRoot===root.id),ids=new Set(rows.map(o=>o.id));remapActorReferences(rows,bindings.filter(b=>ids.has(b.self)),new Map(Object.entries(link.ids)));}}

export function unpackPrefabInstance(objects,root){checkLink(root);return objects.map(o=>{if(o.prefabRoot!==root.id)return o;const next=copy(o);for(const key of ['prefabAsset','prefabRoot','prefabLocalId','prefabLink'])delete next[key];return next;});}
export function revertAllPrefabProperties(objects,root){const l=checkLink(root),rows=worldRows(l.baseline,l),r=rows.find(o=>o.id===root.id);for(const key of ['position','rotation','parent','parentId']){if(Object.hasOwn(root,key))r[key]=copy(root[key]);else delete r[key];}r.prefabLink={...copy(l),conflicts:[]};return objects.filter(o=>o.prefabRoot!==root.id).concat(rows);}

export async function refreshPrefabWorld(objects,read,{validate}={}){if(!objects.some(o=>o.prefabLink))return objects;const definitions=new Map();let next=objects;for(const root of objects.filter(o=>o.prefabLink)){if(!definitions.has(root.prefabAsset))definitions.set(root.prefabAsset,resolvePrefab(root.prefabAsset,read,{validate}));const source=await definitions.get(root.prefabAsset);next=refreshPrefabInstance(next,next.find(o=>o.id===root.id),source).objects;}if(next!==objects){objects.length=0;for(const o of next)objects.push(o);}return objects;}
